import { execFileSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  readFileSync,
  statSync,
  truncateSync,
  writeFileSync,
} from 'node:fs';
import { randomBytes } from 'node:crypto';
import { join, resolve } from 'node:path';

/** Small synthetic videos generated by ffmpeg (lavfi) on first use; the directory is git-ignored. */
export const FIXTURES_DIR = resolve(process.cwd(), 'test/fixtures');

export const FIXTURES = {
  /** h264 High / yuv420p / aac, 6 s 720p, GOP 2 s → remux */
  plain: 'plain.mp4',
  /** VP9 + Opus in Matroska → transcode (codec) */
  vp9: 'vp9.mkv',
  /** plain.mp4 with a 90° display rotation → transcode (rotation), portrait output */
  rotated: 'rotated.mp4',
  /** h264 High 10 / yuv420p10le → transcode (profile) */
  high10: 'high10.mp4',
  /** h264 + mp3 → remux video, re-encode audio */
  mp3audio: 'mp3audio.mp4',
  /** 20 s with a single keyframe → transcode (keyframe interval) */
  longgop: 'longgop.mp4',
  /** mp4 without faststart, cut in half → ffprobe cannot find moov → corrupted */
  broken: 'broken.mp4',
  /** random bytes → corrupted */
  notvideo: 'notvideo.bin',
  /** Plain.mp4 with a phone's tags (title, place, author, device), a chapter and a data track → cleaned */
  tagged: 'tagged.mp4',
  /** Matroska with ASS subtitles under an .mp4 name: an MP4 cannot hold them → cleaned into MKV */
  subtitled: 'subtitled.mp4',
  /** H264 full range (yuvj420p), as cameras and screen recorders write → remux */
  fullrange: 'fullrange.mp4',
  /** The video track of plain.mp4 alone, as a DASH stream's video representation */
  dashVideo: 'dash-video.mp4',
  /** The audio track of plain.mp4 alone, as a DASH stream's audio representation */
  dashAudio: 'dash-audio.m4a',
} as const;
export type FixtureName = keyof typeof FIXTURES;

const ffmpeg = process.env['FFMPEG_PATH'] ?? 'ffmpeg';

function run(args: string[]): void {
  execFileSync(
    ffmpeg,
    ['-hide_banner', '-nostdin', '-y', '-loglevel', 'error', ...args],
    {
      stdio: ['ignore', 'ignore', 'inherit'],
    },
  );
}

const SRC = (sec: number, size = '1280x720') => [
  '-f',
  'lavfi',
  '-i',
  `testsrc2=size=${size}:rate=30`,
  '-f',
  'lavfi',
  '-i',
  'sine=frequency=440:sample_rate=48000',
  '-t',
  String(sec),
];

/** Generates every fixture that is missing and returns absolute paths. */
export function ensureFixtures(): Record<FixtureName, string> {
  mkdirSync(FIXTURES_DIR, { recursive: true });
  const path = (name: FixtureName) => join(FIXTURES_DIR, FIXTURES[name]);
  const missing = (name: FixtureName) =>
    !existsSync(path(name)) || statSync(path(name)).size === 0;

  if (missing('plain'))
    run([
      ...SRC(6),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-pix_fmt',
      'yuv420p',
      '-g',
      '60',
      '-c:a',
      'aac',
      '-b:a',
      '96k',
      '-movflags',
      '+faststart',
      path('plain'),
    ]);
  if (missing('dashVideo'))
    run(['-i', path('plain'), '-map', '0:v', '-c', 'copy', path('dashVideo')]);
  if (missing('dashAudio'))
    run(['-i', path('plain'), '-map', '0:a', '-c', 'copy', path('dashAudio')]);
  if (missing('vp9'))
    run([
      ...SRC(6),
      '-c:v',
      'libvpx-vp9',
      '-deadline',
      'realtime',
      '-cpu-used',
      '8',
      '-b:v',
      '1M',
      '-c:a',
      'libopus',
      path('vp9'),
    ]);
  if (missing('rotated'))
    run([
      '-display_rotation',
      '90',
      '-i',
      path('plain'),
      '-c',
      'copy',
      path('rotated'),
    ]);
  if (missing('high10'))
    run([
      ...SRC(6),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-profile:v',
      'high10',
      '-pix_fmt',
      'yuv420p10le',
      '-c:a',
      'aac',
      path('high10'),
    ]);
  if (missing('mp3audio'))
    run([
      ...SRC(6),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-pix_fmt',
      'yuv420p',
      '-g',
      '60',
      '-c:a',
      'libmp3lame',
      '-b:a',
      '96k',
      path('mp3audio'),
    ]);
  if (missing('longgop'))
    run([
      ...SRC(20, '640x360'),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-pix_fmt',
      'yuv420p',
      '-g',
      '900',
      '-keyint_min',
      '900',
      '-sc_threshold',
      '0',
      '-c:a',
      'aac',
      path('longgop'),
    ]);
  if (missing('broken')) {
    run([
      ...SRC(6),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-pix_fmt',
      'yuv420p',
      '-c:a',
      'aac',
      path('broken'),
    ]);
    truncateSync(path('broken'), Math.floor(statSync(path('broken')).size / 2));
  }
  if (missing('notvideo'))
    writeFileSync(path('notvideo'), randomBytes(64 * 1024));
  if (missing('fullrange'))
    run([
      ...SRC(6, '640x360'),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-pix_fmt',
      'yuvj420p',
      '-g',
      '60',
      '-c:a',
      'aac',
      path('fullrange'),
    ]);
  if (missing('tagged')) {
    const chapters = join(FIXTURES_DIR, 'chapters.txt');
    writeFileSync(
      chapters,
      ';FFMETADATA1\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=0\nEND=3000\ntitle=Bedroom\n',
    );
    run([
      '-i',
      path('plain'),
      '-i',
      chapters,
      '-map',
      '0',
      '-map_chapters',
      '1',
      '-c',
      'copy',
      '-metadata',
      'title=Secret title',
      '-metadata',
      'comment=shot at home',
      '-metadata',
      'artist=Real Name',
      '-metadata',
      'location=+55.7558+037.6173/',
      '-metadata',
      'creation_time=2024-03-01T12:00:00Z',
      '-metadata:s:v:0',
      'handler_name=iPhone camera',
      '-movflags',
      '+use_metadata_tags',
      path('tagged'),
    ]);
  }
  if (missing('subtitled')) {
    const subs = join(FIXTURES_DIR, 'subs.ass');
    writeFileSync(
      subs,
      [
        '[Script Info]',
        'ScriptType: v4.00+',
        '',
        '[V4+ Styles]',
        'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
        'Style: Default,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,1,0,2,10,10,10,1',
        '',
        '[Events]',
        'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text',
        'Dialogue: 0,0:00:00.00,0:00:02.00,Default,,0,0,0,,Hello',
        '',
      ].join('\n'),
    );
    run([
      '-i',
      path('plain'),
      '-i',
      subs,
      '-map',
      '0',
      '-map',
      '1',
      '-c:v',
      'copy',
      '-c:a',
      'copy',
      '-c:s',
      'ass',
      '-metadata',
      'title=Secret title',
      '-f',
      'matroska',
      path('subtitled'),
    ]);
  }

  return Object.fromEntries(
    (Object.keys(FIXTURES) as FixtureName[]).map((n) => [n, path(n)]),
  ) as Record<FixtureName, string>;
}

export function fixtureBytes(name: FixtureName): Buffer {
  return readFileSync(join(FIXTURES_DIR, FIXTURES[name]));
}
